import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·34","description":"易小帖 - 卷一·34","frontmatter":{"title":"卷一·34","description":"易小帖 - 卷一·34"},"headers":[],"relativePath":"zh/classics/yixiaotie/034.md","filePath":"zh/classics/yixiaotie/034.md"}'),o={name:"zh/classics/yixiaotie/034.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·34",tabindex:"-1"},[r("卷一·34 "),e("a",{class:"header-anchor",href:"#卷一·34","aria-label":"Permalink to “卷一·34”"},"​")],-1),e("p",null,"樽酒簋貳，以坎水有酒象。坎之窞有簋缶之象，若鄭康成謂四以互體居震之上爻，而其辰在醜，醜上值鬥，可以斟酒。又鬥上有建星，其形似簋，建星上有弁星，其形又如缶。此又以卦象方位解爻義者。至離之九三「鼓缶而歌」又雲：此艮爻也（離從遯來，故有艮爻），位在醜，醜上值弁星似缶。則以艮震皆東北方卦，皆在醜位，故雲是坎合艮震（皆互卦）。其為簋為缶，又不止震上一爻如此。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
